INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (19, 30, 'theory', 'Quiz: QEMU: threads, the event loop, virtio-blk');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 30, 0, 'Which QEMU thread, with the KVM accelerator, runs ioctl(KVM_RUN) for a virtual processor?', '["The main thread, where the main loop runs", "A separate thread per vCPU, named \"CPU n/KVM\" with debug-threads", "A worker thread from the pool for blocking jobs", "The kernel itself, QEMU calls it once at startup"]', 1, 'kvm_start_vcpu_thread creates a thread for every vCPU, and it spins kvm_cpu_exec and KVM_RUN inside it. The main thread is busy with the main loop, and worker runs blocking calls.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 30, 1, 'What happens to the Big QEMU Lock (BQL) in kvm_cpu_exec before the KVM_RUN loop?', '["It is held for the whole loop so that the guest cannot change memory", "It is taken again before every ioctl", "It is split evenly between the vCPUs", "It is released: the guest runs without the lock, and device code takes it itself when needed"]', 3, 'kvm_cpu_exec calls bql_unlock before the loop; the IO and MMIO handlers run outside the lock, and device memory takes the lock in prepare_mmio_access unless the region is marked lockless_io.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 30, 2, 'Why is an ioeventfd set on the notify address of a virtio-blk queue?', '["A guest write to that address only signals an eventfd in the kernel, with no exit to QEMU, and the context''s handler wakes on the descriptor", "So that the guest can read the disk directly, bypassing QEMU", "So that QEMU can turn off the guest''s interrupts", "So that every request is handled in the main loop under the BQL"]', 0, 'By the KVM_IOEVENTFD documentation a write at the registered address signals the event instead of an exit. The queue''s AioContext watches the descriptor, the main one or an iothread''s.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 30, 3, 'In what order does aio_poll (QEMU 10.2.0) do its work after the wait?', '["Timers, ready fds, deferred calls", "Ready fds, timers, deferred calls", "io_uring completions, deferred calls (BHs), ready fd handlers, timers", "Only timers; the main thread does the rest"]', 2, 'In util/aio-posix.c after the wait come fdmon_ops->dispatch (io_uring completions), aio_bh_poll, aio_dispatch_ready_handlers and timerlistgroup_run_timers, in exactly that order.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 30, 4, 'How does the completion of a request handled in an iothread reach the guest?', '["The iothread raises the guest interrupt itself, taking the BQL", "virtqueue_push writes an element into the used ring, and virtio_notify signals a notifier (an eventfd) which, with KVM and MSI-X, is tied to an irqfd", "The guest polls the used ring, QEMU signals nothing", "With a SIGUSR1 signal to the vCPU thread"]', 1, 'The interrupt path needs the BQL, so virtio_irq picks the guest notifier for an iothread; KVM turns it into an interrupt through an irqfd (KVM_IRQFD). The used ring is written without the BQL.');
